def resolve(path, cwd, links):
    # Normalize input path to a list of components
    if path.startswith('/'):
        current = []
    else:
        current = cwd.strip('/').split('/') if cwd != '/' else []

    # Split path into components, filtering out empty and '.' components
    components = [c for c in path.split('/') if c and c != '.']

    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]

        if comp == '..':
            if current:
                current.pop()
            i += 1
        else:
            current.append(comp)

            # Build the canonical absolute path so far
            canonical_path = '/' + '/'.join(current) if current else '/'

            # Check if this path is a symlink
            if canonical_path in links:
                link_count += 1
                if link_count > 8:
                    return None

                target = links[canonical_path]

                # Remove the appended component since we're resolving the link
                current.pop()

                # Process the link target
                if target.startswith('/'):
                    current = []
                    target_components = [c for c in target.split('/') if c and c != '.']
                else:
                    # Relative link - relative to the directory containing the link
                    target_components = [c for c in target.split('/') if c and c != '.']

                # Insert remaining components after the link components
                remaining = components[i + 1:]
                components = target_components + remaining
                i = 0
            else:
                i += 1

    # Build the final result
    if not current:
        return '/'
    return '/' + '/'.join(current)

